{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "london_eye_image",
        "qr_comparison_section_stack",
        "implementation_security_section_stack",
        "quick_actions_section_stack",
        "sources_section_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "London Workshop QR Guide",
        "variant": "h1"
      },
      "children": []
    },
    "london_eye_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/6/67/London_Eye_at_Night.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "qr_comparison_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "qr_comparison_header_stack",
        "qr_comparison_table"
      ]
    },
    "qr_comparison_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "qr_comparison_title_h2",
        "qr_comparison_icon"
      ]
    },
    "qr_comparison_title_h2": {
      "type": "Text",
      "props": {
        "text": "QR Code Type Comparison",
        "variant": "h2"
      },
      "children": []
    },
    "qr_comparison_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/calendar.svg"
      },
      "children": []
    },
    "qr_comparison_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "criteria",
            "label": "Criteria"
          },
          {
            "key": "static_qr_codes",
            "label": "Static QR Codes"
          },
          {
            "key": "dynamic_qr_codes",
            "label": "Dynamic QR Codes"
          }
        ],
        "rows": [
          {
            "criteria": "Check-in Speed",
            "static_qr_codes": "High (Fixed data)",
            "dynamic_qr_codes": "High (Server-side)"
          },
          {
            "criteria": "Analytics",
            "static_qr_codes": "None",
            "dynamic_qr_codes": "Real-time scan logs"
          },
          {
            "criteria": "URL flexibility",
            "static_qr_codes": "Permanent",
            "dynamic_qr_codes": "Changeable anytime"
          },
          {
            "criteria": "Best For",
            "static_qr_codes": "WiFi/Fixed links",
            "dynamic_qr_codes": "Digital brochures"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "implementation_security_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "implementation_security_header_stack",
        "scanning_setup_text",
        "quishing_prevention_text"
      ]
    },
    "implementation_security_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "implementation_security_title_h2",
        "implementation_security_icon"
      ]
    },
    "implementation_security_title_h2": {
      "type": "Text",
      "props": {
        "text": "Implementation & Security",
        "variant": "h2"
      },
      "children": []
    },
    "implementation_security_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/laptop.svg"
      },
      "children": []
    },
    "scanning_setup_text": {
      "type": "Text",
      "props": {
        "text": "Scanning Station Setup: Ensure 100-lux lighting, use matte-finish table stands, and provide a backup paper list for the 50 participants.",
        "variant": "body"
      },
      "children": []
    },
    "quishing_prevention_text": {
      "type": "Text",
      "props": {
        "text": "Quishing Prevention: Use branded short-links, verify all URLs before printing, and display the destination domain clearly on the placard.",
        "variant": "body"
      },
      "children": []
    },
    "quick_actions_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_actions_title_h3",
        "quick_actions_buttons_stack"
      ]
    },
    "quick_actions_title_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_buttons_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "checkin_button",
        "brochure_button"
      ]
    },
    "checkin_button": {
      "type": "Button",
      "props": {
        "label": "Check-in Portal"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://london-workshop.co.uk/checkin"
          }
        }
      },
      "children": []
    },
    "brochure_button": {
      "type": "Button",
      "props": {
        "label": "View Brochure"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://london-workshop.co.uk/brochure"
          }
        }
      },
      "children": []
    },
    "sources_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "sources_title_h3",
        "sources_buttons_stack"
      ]
    },
    "sources_title_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_buttons_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "london_gov_button",
        "ncsc_button"
      ]
    },
    "london_gov_button": {
      "type": "Button",
      "props": {
        "label": "London Event Safety"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.london.gov.uk/what-we-do/business-and-economy"
          }
        }
      },
      "children": []
    },
    "ncsc_button": {
      "type": "Button",
      "props": {
        "label": "QR Security Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ncsc.gov.uk/guidance/qr-codes"
          }
        }
      },
      "children": []
    }
  }
}
